  quizData.forEach(q => {
    const checked = Array.from(
      document.querySelectorAll(`input[name="${q.id}"]:checked`)
    ).map(el => el.value);

    const correct = q.correct.slice().sort().join(",");
    const given   = checked.slice().sort().join(",");

    if (correct === given) totalCorrect++;
  });

  const total   = quizData.length;
  const banner  = document.getElementById("result-banner");
  const pct     = totalCorrect / total;

  banner.className = "result-banner show " + (pct === 1 ? "success" : pct >= 0.5 ? "partial" : "incorrect");

  const icon = pct === 1
    ? `<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>`
    : `<svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>`;

  const msg = pct === 1
    ? "Perfect score! You nailed every question."
    : pct >= 0.5
    ? `Good effort! You got ${totalCorrect} out of ${total} correct.`
    : `You got ${totalCorrect} out of ${total} correct. Keep studying!`;

  banner.innerHTML = `${icon} <span>${msg}</span>`;
  banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

